('gate-puzzler','basic','What is A · A in Boolean algebra?',ARRAY['A','0','1','A'''],0,'A AND A = A (idempotent).',10),
('gate-puzzler','basic','What is NOT(NOT A)?',ARRAY['A','0','1','A'''],0,'Double negation cancels out.',10),
