('gate-puzzler','basic','Which gate has a truth table with only one 1 output?',ARRAY['AND','NAND','NOR','XOR'],0,'AND has one 1 row (both inputs 1).',10),
('gate-puzzler','basic','What is the output of XOR(1,0)?',ARRAY['1','0','High-Z','Undefined'],0,'XOR(1,0) = 1.',10),
('gate-puzzler','basic','What is the output of XNOR(1,1)?',ARRAY['1','0','High-Z','Undefined'],0,'XNOR outputs 1 when inputs are equal.',10),
