('gate-puzzler','basic','What is A + A'' in Boolean algebra?',ARRAY['1','0','A','A'''],0,'A OR NOT A = 1 (complementarity).',10),
('gate-puzzler','basic','Which two gates are called universal gates?',ARRAY['NAND and NOR','AND and OR','XOR and XNOR','NOT and Buffer'],0,'Both NAND and NOR are functionally complete.',10),
('gate-puzzler','basic','What is the output of AND(1,0)?',ARRAY['0','1','High-Z','Undefined'],0,'AND(1,0) = 0.',10),
('gate-puzzler','basic','What is the output of OR(1,0)?',ARRAY['1','0','High-Z','Undefined'],0,'OR(1,0) = 1.',10),
('gate-puzzler','intermediate','Simplify: A + AB',ARRAY['A','B','A+B','AB'],0,'A + AB = A(1+B) = A (absorption).',15),
